const g=new THREE.Group();
const rnd=ctx.rngFrom(21);
const mat=ctx.makeMat({color:'#7bd88f',opacity:0.6,rough:0.5});
const start=new THREE.Vector3(-1.3,1.7,0.9);
for(let k=0;k<16;k++){
  const th=2*Math.PI*rnd(), ph=Math.acos(2*rnd()-1);
  const end=new THREE.Vector3(Math.sin(ph)*Math.cos(th),Math.cos(ph),Math.sin(ph)*Math.sin(th)).multiplyScalar(3.7);
  const mid=start.clone().lerp(end,0.5).add(new THREE.Vector3(rnd()-.5,rnd()-.5,rnd()-.5).multiplyScalar(0.5));
  g.add(new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3([start,mid,end]),24,0.018,5,false),mat));
}
return g;
